"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[74290],{3331:(e,n,i)=>{i.d(n,{R:()=>a,x:()=>s});var t=i(36672);const r={},o=t.createContext(r);function a(e){const n=t.useContext(o);return t.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function s(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:a(e.components),t.createElement(o.Provider,{value:n},e.children)}},45271:(e,n,i)=>{i.r(n),i.d(n,{assets:()=>d,contentTitle:()=>s,default:()=>m,frontMatter:()=>a,metadata:()=>t,toc:()=>l});const t=JSON.parse('{"id":"2023/04/15","title":"2023-04-15","description":"Grootste eiland in een meer op een eiland in een meer op een eiland (2007)","source":"@site/i18n/nl/docusaurus-plugin-content-docs/current/2023/04/15.md","sourceDirName":"2023/04","slug":"/2023/04/15","permalink":"/nl/2023/04/15","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/nl/docusaurus-plugin-content-docs//current/2023/04/15.md","tags":[],"version":"current","frontMatter":{"localized_date":"15 april 2023","top_news":"Grootste eiland in een meer op een eiland in een meer op een eiland (2007)"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-16","permalink":"/nl/2023/04/16"},"next":{"title":"2023-04-14","permalink":"/nl/2023/04/14"}}');var r=i(23420),o=i(3331);const a={localized_date:"15 april 2023",top_news:"Grootste eiland in een meer op een eiland in een meer op een eiland (2007)"},s="2023-04-15",d={},l=[{value:"Grootste eiland in een meer op een eiland in een meer op een eiland (2007)",id:"grootste-eiland-in-een-meer-op-een-eiland-in-een-meer-op-een-eiland-2007",level:2},{value:"Vraag Zijproject van meer dan $2k maandelijkse inkomsten? Wat is uw project?",id:"vraag-zijproject-van-meer-dan-2k-maandelijkse-inkomsten-wat-is-uw-project",level:2},{value:"Spaanse klimmer duikt op na 500 dagen in grot",id:"spaanse-klimmer-duikt-op-na-500-dagen-in-grot",level:2},{value:"Temporele kwaliteitsvermindering in AI-modellen",id:"temporele-kwaliteitsvermindering-in-ai-modellen",level:2},{value:"De FAA heeft SpaceX toestemming gegeven om zijn Starship-raket te lanceren...",id:"de-faa-heeft-spacex-toestemming-gegeven-om-zijn-starship-raket-te-lanceren",level:2},{value:"Prompt injectie: wat is het ergste dat kan gebeuren?",id:"prompt-injectie-wat-is-het-ergste-dat-kan-gebeuren",level:2},{value:"Een open source AI-tool om kindertekeningen te animeren",id:"een-open-source-ai-tool-om-kindertekeningen-te-animeren",level:2},{value:"Antwoorden op opmerkingen over het ontwerp van onze webpagina",id:"antwoorden-op-opmerkingen-over-het-ontwerp-van-onze-webpagina",level:2},{value:"ESA&#39;s Juice gaat op zoek naar de geheimen van Jupiters ijzige manen.",id:"esas-juice-gaat-op-zoek-naar-de-geheimen-van-jupiters-ijzige-manen",level:2},{value:"LLM-toepassingen bouwen voor productie",id:"llm-toepassingen-bouwen-voor-productie",level:2}];function c(e){const n={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,o.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(n.header,{children:(0,r.jsx)(n.h1,{id:"2023-04-15",children:"2023-04-15"})}),"\n",(0,r.jsx)(n.h2,{id:"grootste-eiland-in-een-meer-op-een-eiland-in-een-meer-op-een-eiland-2007",children:"Grootste eiland in een meer op een eiland in een meer op een eiland (2007)"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"https://www.elbruz.org/special-projects/islands-and-lakes/",children:"Origineel"}),".\nHet bericht vermeldt het grootste eiland, het grootste meer en het grootste eiland in een meer. Het grootste eiland in een meer op een eiland is Vulcan Point in Crater Lake op Vulcano Island in Lake Taal op Luzon. Deze website wordt onderhouden door de Elbruz Department of Public Information met de technische ondersteuning van de Information Technology Services Division."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35567026",children:"Discussion Service"}),".\nEen post van Hacker News bespreekt het grootste eiland in een meer op een eiland, waarbij gebruikers de authenticiteit van sommige bronnen in twijfel trekken en vriendschappelijke geintjes maken over het vinden van het kleinste eiland met een rivier. Andere onderwerpen, zoals het gebrekkige concept van continenten en hun definitie, de classificatie van Australi\xeb als continent of regio, en de vraag of Midden-Amerika kan worden beschouwd als een continent, worden besproken door gebruikers op Discussion Service, waarbij kritisch denken over gevestigde concepten en definities wordt bevorderd."]}),"\n",(0,r.jsx)(n.h2,{id:"vraag-zijproject-van-meer-dan-2k-maandelijkse-inkomsten-wat-is-uw-project",children:"Vraag Zijproject van meer dan $2k maandelijkse inkomsten? Wat is uw project?"}),"\n",(0,r.jsx)(n.p,{children:"De titel van de post vraagt naar nevenprojecten met meer dan $2k maandelijkse inkomsten, en gebruikers hebben hun eigen projecten in de commentaren gedeeld, zoals een SaaS voor het beheer van huurwoningen en een tool voor sociale-mediamarketing. Sommige gebruikers waarschuwen dat inkomsten niet noodzakelijk correleren met succes of winstgevendheid, terwijl anderen tips geven om geld te verdienen en een klantenbestand op te bouwen."}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35567822",children:"Discussion Service"}),".\nEen Discussion Service-gebruiker vraagt om suggesties voor zijprojecten die meer dan $2k per maand opbrengen, en krijgt verschillende antwoorden, waaronder een Bluetooth-controlleradapterproject dat $3k per maand opbrengt en suggesties voor inkomsten uit donaties, reclame en steun van fabrikanten. HTTP Toolkit genereert genoeg maandelijkse inkomsten waarmee de maker fulltime werkt, met als belangrijkste verkoopargumenten gebruiksgemak en de mogelijkheid om elk type HTTP(S)-verkeer te onderscheppen en te wijzigen. Daarnaast worden onder meer een succesvol passieproject, een eetgroep en unieke waardeproposities voor kopers van buitenlands onroerend goed besproken."]}),"\n",(0,r.jsx)(n.h2,{id:"spaanse-klimmer-duikt-op-na-500-dagen-in-grot",children:"Spaanse klimmer duikt op na 500 dagen in grot"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"https://www.cbc.ca/news/world/spain-cave-500-days-beatriz-flamini-1.6810428",children:"Origineel"}),".\nKan geen samenvatting geven aangezien de gegeven tekst een foutmelding is en geen relevante informatie bevat."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35571481",children:"Discussion Service"}),".\nSpaanse klimster vestigt een wereldrecord door 500 dagen ondergronds in een grot door te brengen voor een experiment, en er komt een documentaire uit over haar reis. Discussies onder gebruikers vari\xebren van voorwaardelijkheid en zelfmoordmoraal tot de effecten van lange perioden zonder zonlicht en de eenvoud van religieuze overtuigingen."]}),"\n",(0,r.jsx)(n.h2,{id:"temporele-kwaliteitsvermindering-in-ai-modellen",children:"Temporele kwaliteitsvermindering in AI-modellen"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"https://www.nannyml.com/blog/91-of-ml-perfomance-degrade-in-time",children:"Origineel"}),'.\nUit een recente studie van MIT, Harvard en de Universiteit van Monterrey blijkt dat 91% van de modellen voor machinaal leren in de loop van de tijd een kwaliteitsvermindering ondergaan als gevolg van gegevensdrift, de zogenaamde "AI-veroudering". In de studie werden drie significante degradatiepatronen waargenomen en werd geconcludeerd dat voortdurende controle noodzakelijk is om dit probleem te beperken. In een ander wetenschappelijk artikel wordt voorgesteld het model te hertrainen met nieuw gelabelde gegevens om dit probleem aan te pakken, maar wordt gewezen op de behoefte aan een effici\xebnt en robuust mechanisme voor automatische hertraining en controle-instrumenten zoals NannyML om storingen te voorkomen.']}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35566145",children:"Discussion Service"}),".\nDeskundigen bespreken de mogelijke kwaliteitsvermindering in de tijd van AI-modellen, omdat ze oplossingen uit het verleden kunnen reproduceren, wat leidt tot oververzadigde inhoud. Hoewel gebruikers bewijs leveren voor beide opvattingen dat AI-modellen nieuwe concepten genereren of beperkt zijn tot bestaande gegevens, wordt gewezen op de conservatieve vooringenomenheid van de huidige opleidingsgegevens en het ontbreken van een duidelijk inzicht in de getransformeerde ruimte. Onderzoek van de Northwestern University identificeert de degradatiepatronen van modellen voor machinaal leren met datasets uit verschillende bedrijfstakken, met een oproep om modellen opnieuw te trainen op nieuwe gegevens en de noodzaak van menselijk toezicht."]}),"\n",(0,r.jsx)(n.h2,{id:"de-faa-heeft-spacex-toestemming-gegeven-om-zijn-starship-raket-te-lanceren",children:"De FAA heeft SpaceX toestemming gegeven om zijn Starship-raket te lanceren..."}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"https://arstechnica.com/science/2023/04/green-light-go-spacex-receives-a-launch-license-from-the-faa-for-starship/",children:"Origineel"}),".\nDe FAA heeft SpaceX toestemming gegeven om zijn Starship-raket te lanceren vanuit Zuid-Texas, wat de laatste regelgevende stap is die het bedrijf moest nemen voordat het toestemming krijgt om te vliegen met de grootste raket ooit gebouwd. SpaceX zal naar verwachting dit weekend een laatste gereedheidsonderzoek houden voordat het besluit neemt om door te gaan met een lanceerpoging, die maandag al zou kunnen plaatsvinden. Het lanceervenster zal naar verwachting om 7 uur plaatselijke tijd openen in Texas."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35575298",children:"Discussion Service"}),".\nSpaceX heeft toestemming gekregen van de FAA om zijn Starship-raket te lanceren, waarbij de discussie zich toespitst op de betekenis hiervan voor het begin van een nieuw tijdperk in de ruimteverkenning. Ondanks de opwinding over de recente goedkeuring werden ook mogelijke problemen en vertragingen bij de lancering besproken, met inzicht in de ontwikkeling en de potenti\xeble impact van de Starship-raket."]}),"\n",(0,r.jsx)(n.h2,{id:"prompt-injectie-wat-is-het-ergste-dat-kan-gebeuren",children:"Prompt injectie: wat is het ergste dat kan gebeuren?"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"https://simonwillison.net/2023/Apr/14/worst-that-can-happen/",children:"Origineel"}),".\nTechdeskundigen waarschuwen voor de ernstige gevolgen van prompt injection in LLM's, die onder meer in bepaalde toepassingen zoals ChatGPT Plugins en ReAct pattern tot kwetsbaarheden kunnen leiden, zonder dat er een oplossing is die 100% bescherming garandeert. Ondanks het opleiden van ontwikkelaars blijft prompt injection onopgelost, en kan het risico van data exfiltratie en SEO optimalisatie hacken de ontwikkeling van LLM's schaden. OpenAI's GPT-4 biedt een \"system prompt\"-functie om prompt injection te voorkomen, maar recente ontwikkelingen in LLM's kunnen het kwetsbaarheidsrisico vergroten."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35572290",children:"Discussion Service"}),".\nHet commentaar van Hacker News bespreekt prompt injection-aanvallen op taalmodellen en stelt voor om out-of-band middelen te gebruiken, honeypots te maken en de beveiligingsmaatregelen te verhogen. De beperkingen van natuurlijke taal als middel om grenzen voor taalmodellen te codificeren worden ook onderzocht, waarbij sommigen voorstellen om jaarlijkse beveiligingstraining en ACL-bewuste modellen te gebruiken om het probleem aan te pakken. De kwetsbaarheid van LLM's voor prompt injection-aanvallen krijgt steeds meer aandacht van technische deskundigen, met zorgen over slechte actoren die misbruik maken van slecht beveiligde LLM's. De nieuwste ontwikkelingen op het gebied van modellen voor machinaal leren hebben geleid tot nieuwe kwetsbaarheden, waaronder prompt injection-aanvallen, waarvan onderzoekers de gebruikers aansporen deze als onvermijdelijk te beschouwen. De moeilijkheden van prompt injection-aanvallen op taalmodellen en mogelijke oplossingen, waaronder het implementeren van een menselijke prompt of het scheiden van gebruikersgegevens en systeemgegevens, worden ook besproken."]}),"\n",(0,r.jsx)(n.h2,{id:"een-open-source-ai-tool-om-kindertekeningen-te-animeren",children:"Een open source AI-tool om kindertekeningen te animeren"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"https://github.com/facebookresearch/AnimatedDrawings",children:"Origineel"}),".\nFacebook AI Research heeft een AI-tool ontwikkeld die menselijke figuren kan animeren vanuit kindertekeningen, die beschikbaar is gemaakt op GitHub. De tool gebruikt configuratiebestanden voor het bewegen en renderen van personages, en kan animaties in verschillende formaten exporteren. De open-source repo bevat modelgewichten, figuurdetectie en een As-Rigid-As-Possible Shape Manipulation algoritme voor ontwikkelaars."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35565681",children:"Discussion Service"}),".\nFacebook Research heeft een open-source AI-tool vrijgegeven om kindertekeningen te animeren, wat mogelijk leidt tot innovaties in realistische tekenfilm- en CGI-personages, maar sommige gebruikers denken dat het project slechts een algoritme is, en anderen beschouwen de tool als de onderkant van animatie, terwijl anderen geloven dat de onderkant van animatie van door AI gegenereerde beelden binnen enkele jaren indrukwekkend zou kunnen worden."]}),"\n",(0,r.jsx)(n.h2,{id:"antwoorden-op-opmerkingen-over-het-ontwerp-van-onze-webpagina",children:"Antwoorden op opmerkingen over het ontwerp van onze webpagina"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"https://research.exoticsilicon.com/articles/replying_to_comments",children:"Origineel"}),".\nExotic Silicon reageert op kritiek op het webdesign en legt hun unieke en vooruitstrevende stijl uit waarin verouderde ontwerpelementen worden vermeden. Ze richten zich op leesbaarheid en het gebruik van CSS om materiaalpresentaties te verbeteren in plaats van voor showboating. Het bedrijf benadrukt hun toegankelijkheid en gebruiksvriendelijkheid en adviseert gebruikers hun browsers te configureren en constructieve kritiek te vragen voor verbetering."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35567285",children:"Discussion Service"}),".\nHacker News gebruikers bespreken het webontwerp van de website van Exotic Silicon, met opmerkingen over toegankelijkheid, lettergrootte en onconventionele ontwerpkeuzes. Gebruikers discussi\xebren over de voordelen van een uniek ontwerp om zich te onderscheiden van de meer standaard esthetiek. Het artikel in Tech Times gaat over reacties op de website van Exotic Silicon, waaronder kritiek op de vijandigheid tegenover toegankelijkheid en gemengde meningen over de unieke stijl. Experts discussi\xebren of het ontwerp van websites prioriteit moet geven aan toegankelijkheid of zich moet aanpassen aan de behoeften en voorkeuren van gebruikers."]}),"\n",(0,r.jsx)(n.h2,{id:"esas-juice-gaat-op-zoek-naar-de-geheimen-van-jupiters-ijzige-manen",children:"ESA's Juice gaat op zoek naar de geheimen van Jupiters ijzige manen."}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"https://www.esa.int/Science_Exploration/Space_Science/Juice/ESA_s_Juice_lifts_off_on_quest_to_discover_secrets_of_Jupiter_s_icy_moons",children:"Origineel"}),".\nESA's Jupiter Icy Moons Explorer (Juice) is met succes gelanceerd met een Ariane 5-raket vanuit Frans Guyana om de geheimen van de oceaanwerelden rond Jupiters ijzige manen, waaronder Europa, Ganymedes en Callisto, te ontdekken en de mogelijkheid van leven buiten de aarde aan het licht te brengen. Juice zal 35 flybys maken van de drie grote manen terwijl hij rond Jupiter draait voordat hij van baan verandert naar Ganymedes, waarbij hij de interne temperaturen stabiel houdt met meerlaagse isolatie terwijl hij aan de buitenkant meer dan 250 \xbaC kan bereiken tijdens de flyby van Venus en -230 \xbaC bij Jupiter, aangedreven door zonnepanelen die om 15:33 CEST zijn uitgeklapt."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35574177",children:"Discussion Service"}),".\nESA's Juice ruimtevaartuig is begonnen aan zijn 11-jarige expeditie om Jupiters ijzige manen te onderzoeken in de hoop buitenaards leven te ontdekken. Discussion Service-gebruikers delen hun gedachten over reistijd, beperkingen van het energiebeheer, voordelen van de nuttige lading, nucleaire voortstuwing en mislukkingen van missies in het verleden, terwijl ze ook vraagtekens zetten bij de directe inzameling van zonne-energie op Jupiter, brandstofopslag, verkenning van Uranus en Neptunus, en zelfs gekscherend verwijzen naar de Fermi-paradox."]}),"\n",(0,r.jsx)(n.h2,{id:"llm-toepassingen-bouwen-voor-productie",children:"LLM-toepassingen bouwen voor productie"}),"\n",(0,r.jsxs)(n.p,{children:["(",(0,r.jsx)(n.a,{href:"https://huyenchip.com/2023/04/11/llm-engineering.html",children:"https://huyenchip.com/2023/04/11/llm-engineering.html"}),").\nHet artikel bespreekt de uitdagingen van het bouwen van productieklare LLM-toepassingen, waaronder het beperken van ambigu\xefteit en het optimaliseren van de prestaties. Het onderzoekt de voordelen en overwegingen van het gebruik van API's zoals OpenAI, prompting en finetuning bij LLM-optimalisatie. Veelbelovende use cases voor LLM's worden ook besproken, waaronder zoek- en aanbevelingsfuncties. Er zijn echter ethische overwegingen en uitdagingen bij het detecteren van door AI gegenereerde inhoud."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35565212",children:"Discussion Service"}),".\nHet artikel bespreekt verschillende manieren om LLM-toepassingen in productie te gebruiken, waarbij bezorgdheid wordt geuit over automatische samenvattingen en vooringenomenheid. Toekomstig potentieel, beperkingen en effectieve modellen worden besproken. Discussies over LLM prompt injection en sparsity van de modelgewichtsmatrix domineren de commentaren, met zorgen over betrouwbaarheid en veiligheid. Ook de inzet van kosteneffici\xebnte LLM-toepassingen en de veroudering van de traditionele academische wereld worden besproken."]})]})}function m(e={}){const{wrapper:n}={...(0,o.R)(),...e.components};return n?(0,r.jsx)(n,{...e,children:(0,r.jsx)(c,{...e})}):c(e)}}}]);